//------------------------>>> Length = √((x₂ - x₁)² + (y₂ - y₁)²)
// ----------------------->>> 1st array >> x >> horizental distance from (0,0) 
// ----------------------->>> 2nd array >> y >> vertical distance from (0,0)


#include<bits/stdc++.h>
using namespace std;

int main(){

int n;
cin >> n;
int x[100],y[100];
double length = 0.0,result = 0.0;

for(int i = 0; i<n; i++) cin>> x[i]>>y[i]; // 1st array >> x (horizental) | 2nd array >> y (vertical)

for(int i= 0; i<n; i++)
    for(int j = i+1; j<n; j++){ // Length = √((x₂ - x₁)² + (y₂ - y₁)²)
        length = (x[j] - x[i])*(x[j] -x[i])+(y[j]-y[i])*(y[j]-y[i]);
        length = sqrt(length);
        result = max(result, length);} // Longest Segment

cout << fixed << setprecision(10) << result << endl; // to get rid of absolute or relative error

return 0;
}

