for( int i = 0;i<n; i++){
    cin >> a[i];

    if(i > 0) {
      pre = a[i-1];
      next = a[i];

      if(next < pre || next == pre){
        cout << a[i-1]; // if condition matched then print the previous one
        break;
      }
    }
    if(i == n-1) cout << a[n-1] << endl; // if condition not matched then print the last one
}

